export const AVATAR_BYTES=200000,PHOTO_INPUT_BYTES=20*1024*1024;
export function avatarPath(uid){if(typeof uid!=='string'||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(uid))throw Error('sign_in_required');return uid.toLowerCase()+'/profile.jpg';}
export function cropRect(width,height,zoom=1,x=.5,y=.5){if(!Number.isFinite(width)||!Number.isFinite(height)||width<1||height<1||width*height>50000000)throw Error('image_dimensions');const limit=(n,fallback,min,max)=>Number.isFinite(Number(n))?Math.max(min,Math.min(max,Number(n))):fallback;zoom=limit(zoom,1,1,3);const side=Math.min(width,height)/zoom;return {sx:(width-side)*limit(x,.5,0,1),sy:(height-side)*limit(y,.5,0,1),sw:side,sh:side};}
export async function imageKind(file){if(!file||file.size<3||file.size>PHOTO_INPUT_BYTES)throw Error('image_size');const b=new Uint8Array(await file.slice(0,12).arrayBuffer());if(b[0]===255&&b[1]===216&&b[2]===255)return 'jpeg';if([137,80,78,71,13,10,26,10].every((n,i)=>b[i]===n))return 'png';if(String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP')return 'webp';throw Error('image_format');}
